/* One live research model: frequency counts records, never invented interview mentions. */
(()=>{'use strict';
const D=window.MANEGE,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Editorial clustering of related needs. Distinct respondent conditions remain separate records.
const clusters=[
['opslag','Beschikbare en bereikbare opslag',['I01','I03','K05']],
['materiaalwerk','Materiaalonderhoud',['I02']],['educatie','Les- en lezingenruimte',['I04','I05','K06']],
['delen','Gedeeld en multifunctioneel gebruik',['I06','K08','K18']],['buiten','Buitenleren en groene opstellingen',['I07','K11','K12']],
['toegankelijk','Fysieke toegankelijkheid',['I08','K15']],['internet','Internet',['I09','K14']],
['comfort','Comfort en bruikbaar verblijf',['I10','K16']],['av','Audiovisuele voorzieningen',['I11','K17']],
['logistiek','Materiaalopslag en logistiek',['I12','K13']],['beheer','Beheer en aanspreekpunt',['I13','I15','K07']],
['identiteit','Groene identiteit en verenigingstoegang',['I14','K09']],['evenement','Groene evenementen en inrichting',['I16','I17']],
['ontmoeting','Ontmoeting en koffie',['I18','I19','K10']],['betaalbaar','Betaalbaar gebruik',['I20','K02']],
['beschikbaar','Toegang buiten reguliere tijden',['I21','K01']],['determinatie','Werkplekken voor determinatie',['K03','K04']]];
const orgs=()=>[...new Set([...D.wishes.map(w=>w.org),...(D.stakeholders||[]).map(s=>s.name)].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'nl'));
const type=w=>w.type==='Eis'?'Harde eisen':w.type==='Wens'?'Wensen':['Voorkeur','Idee','Bereidheid tot delen'].includes(w.type)?'Voorkeuren':w.type;
const priority=w=>/^(hoog|gemiddeld|laag)$/i.test(w.priority||'')?w.priority[0].toUpperCase()+w.priority.slice(1).toLowerCase():'Nog niet vastgesteld';
const priorityValue=w=>({Hoog:3,Gemiddeld:2,Laag:1}[priority(w)]||0);
function groupOf(w){if(w.group)return{id:w.group,title:D.wishGroups?.[w.group]?.name||clusters.find(c=>c[0]===w.group)?.[1]||w.group};const c=clusters.find(c=>c[2].includes(w.id));return c?{id:c[0],title:c[1]}:{id:'titel-'+String(w.title).toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-'),title:w.title};}
function themes(w){return [...new Set([w.theme,w.room==='opslag'?'Opslag':null,['zaal','buiten'].includes(w.room)?'Educatie':null,w.room?'Ruimtegebruik':null,groupOf(w).id==='delen'?'Multifunctionaliteit':null].filter(Boolean))];}
function filtered(p){const q=(p.get('q')||'').toLocaleLowerCase();return D.wishes.filter(w=>(!p.get('org')||w.org===p.get('org'))&&(!p.get('type')||type(w)===p.get('type'))&&(!p.get('priority')||priority(w)===p.get('priority')||w.priority===p.get('priority'))&&(!p.get('theme')||themes(w).includes(p.get('theme')))&&(!p.get('room')||w.room===p.get('room'))&&(!q||[w.title,w.detail,w.org,w.theme,groupOf(w).title,w.id].join(' ').toLocaleLowerCase().includes(q)));}
function ranking(ws,p=new URLSearchParams()){const groups=new Map;for(const w of ws){const g=groupOf(w);if(!groups.has(g.id))groups.set(g.id,{...g,wishes:[],orgs:new Set});const row=groups.get(g.id);row.wishes.push(w);row.orgs.add(w.org);}const rows=[...groups.values()].map(g=>({...g,orgs:[...g.orgs].sort(),mentions:g.wishes.length,highest:Math.max(...g.wishes.map(priorityValue)),hard:g.wishes.filter(w=>w.type==='Eis').length}));const metric=p.get('metric')==='mentions'?'mentions':'stakeholders',value=g=>metric==='mentions'?g.mentions:g.orgs.length,sort=p.get('sort')||'most';return rows.sort((a,b)=>sort==='alpha'?a.title.localeCompare(b.title,'nl'):sort==='priority'?b.highest-a.highest||b.hard-a.hard||value(b)-value(a)||a.title.localeCompare(b.title,'nl'):(sort==='least'?1:-1)*(value(a)-value(b))||a.title.localeCompare(b.title,'nl'));}
const href=(p,extra)=>'#wensen?'+new URLSearchParams({...Object.fromEntries(p),...extra});
const opts=(values,current)=>'<option value="">Alle</option>'+values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');
function detail(g,p){return `<section class="stake-detail" id="wish-detail" aria-label="Details geselecteerde behoefte"><div class="stake-detail-head"><div><span class="eyebrow">Verdieping · ${g.orgs.map(esc).join(' · ')}</span><h2>${esc(g.title)}</h2></div><a class="btn" href="${esc(href(p,{id:'',group:''}))}">Sluit details ×</a></div><p class="small">Inhoudelijke groepering voor dit overzicht; verschillen en voorwaarden blijven hieronder zichtbaar. Bronbeschrijvingen zijn parafrases, tenzij uitdrukkelijk als letterlijk citaat opgeslagen.</p>${g.wishes.map(w=>`<article class="stake-evidence">${window.ManegeAdmin?.controls(w)||''}<h3>${esc(w.id)} · ${esc(w.org)} — ${esc(w.title)}</h3><div class="legend"><span class="tag ${w.type==='Eis'?'eis':''}">${esc(w.type)}</span><span class="tag">Bronprioriteit: ${esc(w.priority||'Niet vastgesteld')}</span></div><p>${esc(w.detail||'Nadere omschrijving ontbreekt.')}</p>${w.quote?`<blockquote>${esc(w.quote)}</blockquote>`:''}<a href="#bronnen?source=${encodeURIComponent(w.source||'')}">${esc(w.source||'Bron ontbreekt')} · ${esc(w.time||'Passage niet vastgelegd')}</a><p class="small"><b>Functie:</b> ${esc(D.rooms[w.room]?.name||'Nog te specificeren')}. ${esc(D.rooms[w.room]?.sharing||'Gedeeld gebruik nog niet vastgesteld.')}</p>${(w.advice||[]).length?`<p class="small"><b>VIA-T, algemene analytische koppeling:</b> ${(w.advice||[]).map(id=>`<a href="#viat?advice=${encodeURIComponent(id)}">${esc(D.advice[id]?.title||id)}</a>`).join('; ')}. Geen technische inspectie van De Manege.</p>`:'<p class="small muted">Geen specifiek VIA-T-advies aan deze uitspraak gekoppeld.</p>'}<div class="related"><a href="#studio?wish=${encodeURIComponent(w.id)}">Bekijk in Ontwerpstudio →</a>${w.design?`<a href="#strategie?design=${encodeURIComponent(w.design)}&id=${encodeURIComponent(w.id)}">Ontwerpverbanden →</a>`:''}</div></article>`).join('')}</section>`;}
function page(p){const ws=filtered(p),rank=ranking(ws,p),selected=rank.find(g=>g.id===p.get('group')||g.wishes.some(w=>w.id===p.get('id'))),allOrgs=orgs(),most=Math.max(0,...rank.map(g=>g.orgs.length)),shared=rank.filter(g=>g.orgs.length===most).length,hard=ws.filter(w=>w.type==='Eis').length;return `<section class="stakeholders"><div class="eyebrow">Onderzoek · alle stakeholders</div><h1>Stakeholders</h1><p class="stake-intro">${D.wishes.length} onderzoeksuitspraken · ${allOrgs.length} stakeholders in beeld. Vergelijk gedeelde behoeften en bekijk de voorwaarden per stakeholder.</p>${window.ManegeAdmin?.overview()||''}<form class="filters stake-filters" id="stakefilters"><label>Zoeken<input name="q" type="search" placeholder="Wens, stakeholder of trefwoord" value="${esc(p.get('q')||'')}"></label><label>Stakeholder<select name="org">${opts(allOrgs,p.get('org'))}</select></label><label>Type<select name="type">${opts([...new Set(['Harde eisen','Wensen','Voorkeuren',...D.wishes.map(type)])],p.get('type'))}</select></label><label>Thema<select name="theme">${opts([...new Set(D.wishes.flatMap(themes))].sort(),p.get('theme'))}</select></label><label>Prioriteit<select name="priority">${opts(['Hoog','Gemiddeld','Laag','Nog niet vastgesteld'],p.get('priority'))}</select></label><label>Sorteren<select name="sort">${[['most','Meest voorkomende wens'],['least','Minst voorkomende wens'],['priority','Hoogste prioriteit'],['alpha','Alfabetisch']].map(([v,t])=>`<option value="${v}" ${p.get('sort')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Telling<select name="metric"><option value="stakeholders">Unieke stakeholders</option><option value="mentions" ${p.get('metric')==='mentions'?'selected':''}>Vermeldingen / bronrecords</option></select></label><button type="button" class="btn" data-clear>Wis filters</button><details><summary>Meer filters</summary><label>Functie<select name="room"><option value="">Alle functies</option>${Object.values(D.rooms).map(r=>`<option value="${esc(r.id)}" ${p.get('room')===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label></details></form><div class="stake-overview" role="status"><b>${ws.length} van ${D.wishes.length} uitspraken</b><span>${rank.length} behoeften · ${new Set(ws.map(w=>w.org)).size} stakeholders · ${hard} respondenteneisen</span></div><p class="small"><b>${shared} behoefte${shared===1?'':'n'} ${shared===1?'is':'zijn'} binnen deze selectie door ${most} stakeholder${most===1?'':'s'} genoemd.</b> ${hard} respondenteneisen blijven afzonderlijk herkenbaar.</p><h2>Meest voorkomende behoeften</h2><p class="small muted">Standaard telt iedere stakeholder één keer per groep. Vermeldingen telt afzonderlijke bronrecords, geen herhalingen in de volledige opname. Frequentie is geen prioriteit; gelijke aantallen worden alfabetisch geordend. Groepering is een redactionele analyse; klik voor de oorspronkelijke voorwaarden.</p><div class="tablewrap"><table class="matrix stake-ranking"><thead><tr><th>Rang</th><th>Behoefte</th><th>${p.get('metric')==='mentions'?'Bronrecords':'Stakeholders'}</th><th>Genoemd door</th><th>Prioriteit / type</th></tr></thead><tbody>${rank.map((g,i)=>`<tr><td>${i+1}</td><th><a href="${esc(href(p,{group:g.id,id:''}))}">${esc(g.title)}</a></th><td><strong>${p.get('metric')==='mentions'?g.mentions:g.orgs.length}</strong></td><td>${g.orgs.map(esc).join(', ')}</td><td>${g.highest?['','Laag','Gemiddeld','Hoog'][g.highest]:'Nog niet vastgesteld'}${g.hard?`<br><span class="tag eis">${g.hard} respondenteneis${g.hard===1?'':'en'}</span>`:''}</td></tr>`).join('')||'<tr><td colspan="5">Geen resultaten. Pas de filters aan.</td></tr>'}</tbody></table></div>${selected?detail(selected,p):''}<h2>Alle wensen en eisen <span class="muted small">(${ws.length})</span></h2><div class="stake-list">${ws.map(w=>`<a href="${esc(href(p,{id:w.id,group:''}))}" class="stake-row"><span class="id">${esc(w.id)} · ${esc(w.org)}</span><strong>${esc(w.title)}</strong><span class="tag ${w.type==='Eis'?'eis':''}">${esc(w.type)}</span><span class="small muted">${esc(w.theme)}</span><span aria-hidden="true">→</span></a>`).join('')||'<p>Geen resultaten.</p>'}</div></section>`;}
function compare(p){const org=orgs(),r=D.rooms[p.get('room')]||Object.values(D.rooms)[0];return `<h1>Vergelijking tussen stakeholders</h1><p class="intro">Alle geregistreerde stakeholders, per functie. Overeenkomst in functie betekent geen identieke eis.</p><div class="tablewrap"><table class="matrix"><thead><tr><th>Functie</th>${org.map(o=>`<th>${esc(o)}</th>`).join('')}<th>Mogelijk delen?</th></tr></thead><tbody>${Object.values(D.rooms).map(r=>`<tr><th><a href="#vergelijking?room=${encodeURIComponent(r.id)}">${esc(r.name)}</a></th>${org.map(o=>`<td>${D.wishes.filter(w=>w.org===o&&w.room===r.id).map(w=>`<a href="#wensen?id=${encodeURIComponent(w.id)}">${esc(w.title)}</a>`).join('<br>')||'Geen specifieke uitspraak geregistreerd'}</td>`).join('')}<td>${esc(r.sharing)}</td></tr>`).join('')}</tbody></table></div><h2>${esc(r.name)} · uitspraken per stakeholder</h2><div class="grid">${org.map(o=>`<section class="card"><h3>${esc(o)}</h3>${D.wishes.filter(w=>w.room===r.id&&w.org===o).map(w=>`<p><a href="#wensen?id=${encodeURIComponent(w.id)}">${esc(w.id)} · ${esc(w.title)}</a></p>`).join('')||'<p>Geen specifieke uitspraak geregistreerd.</p>'}</section>`).join('')}</div>`;}
window.ManegeResearch={orgMatches:(oldName,newName)=>oldName===newName||(D.stakeholders||[]).some(s=>s.name===newName&&s.aliases?.includes(oldName)),orgs,type,priority,priorityValue,groupOf,themes,filtered,ranking,page,compare};
})();